<?php

declare(strict_types=1);

require_once __DIR__.'/../../../../config/database.php';require_once __DIR__.'/../../../../app/Http/JsonResponse.php';require_once __DIR__.'/../../../../app/Http/Request.php';require_once __DIR__.'/../../../../app/Auth/Authorization.php';require_once __DIR__.'/../../../../app/Auth/ApiAuth.php';require_once __DIR__.'/../../../../app/Support/Validation.php';require_once __DIR__.'/../../../../app/Reports/ReportUpload.php';require_once __DIR__.'/../../../../app/Incident/Workflow.php';require_once __DIR__.'/../../../../app/Audit/AuditLogger.php';
floodguardRequireMethod('POST');$user=floodguardRequireApiUser($pdo,'reports.create_own');$userId=(int)$user['id'];$id=filter_var($_POST['report_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($id===false)floodguardJsonResponse(422,['success'=>false,'message'=>'Valid report_id required.']);
try{$location=floodguardRequiredString($_POST,'location_description',500);$description=floodguardRequiredString($_POST,'flood_description',5000);[$latitude,$longitude]=floodguardReportCoordinates($_POST);$danger=filter_var($_POST['immediate_danger']??false,FILTER_VALIDATE_BOOLEAN);$photo=null;if(isset($_FILES['photo'])&&($_FILES['photo']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE)$photo=floodguardValidateReportPhoto($pdo,$_FILES['photo']);
$stored=null;$pdo->beginTransaction();$stmt=$pdo->prepare('SELECT status,decision_reason FROM flood_reports WHERE id=:id AND reporter_user_id=:user FOR UPDATE');$stmt->execute([':id'=>$id,':user'=>$userId]);$report=$stmt->fetch();if(!$report){$pdo->rollBack();floodguardJsonResponse(404,['success'=>false,'message'=>'Flood report not found.']);}FloodGuardIncidentWorkflow::requireReportTransition($report['status'],'resubmitted');
$revision=$pdo->prepare('SELECT COALESCE(MAX(revision_number),0)+1 FROM flood_report_revisions WHERE flood_report_id=:id');$revision->execute([':id'=>$id]);$revisionNumber=(int)$revision->fetchColumn();
$pdo->prepare('UPDATE flood_reports SET location_description=:location,latitude=:lat,longitude=:lng,flood_description=:description,immediate_danger=:danger,status="resubmitted",submitted_at=NOW() WHERE id=:id')->execute([':location'=>$location,':lat'=>$latitude,':lng'=>$longitude,':description'=>$description,':danger'=>(int)$danger,':id'=>$id]);
$pdo->prepare('INSERT INTO flood_report_revisions (flood_report_id,revision_number,location_description,latitude,longitude,flood_description,immediate_danger,submitted_by,submitted_at) VALUES (:id,:revision,:location,:lat,:lng,:description,:danger,:user,NOW())')->execute([':id'=>$id,':revision'=>$revisionNumber,':location'=>$location,':lat'=>$latitude,':lng'=>$longitude,':description'=>$description,':danger'=>(int)$danger,':user'=>$userId]);
if($photo!==null){$stored=floodguardStoreReportPhoto($photo);$pdo->prepare('INSERT INTO flood_report_photos (flood_report_id,storage_path,original_name,mime_type,file_size_bytes,sha256_hash,uploaded_by) VALUES (:report,:path,:name,:mime,:size,:hash,:user)')->execute([':report'=>$id,':path'=>$stored['storage_path'],':name'=>$photo['original_name'],':mime'=>$photo['mime_type'],':size'=>$photo['size'],':hash'=>$photo['sha256'],':user'=>$userId]);}
$pdo->prepare('INSERT INTO flood_report_status_history (flood_report_id,from_status,to_status,reason,changed_by,changed_at) VALUES (:id,"correction_requested","resubmitted",NULL,:user,NOW())')->execute([':id'=>$id,':user'=>$userId]);floodguardAudit($pdo,$userId,'flood_report.resubmitted','flood_report',(int)$id,['status'=>'correction_requested'],['status'=>'resubmitted','revision'=>$revisionNumber]);$pdo->commit();floodguardJsonResponse(200,['success'=>true,'message'=>'Corrected flood report resubmitted.','data'=>['id'=>(int)$id,'status'=>'resubmitted','revision_number'=>$revisionNumber]]);
}catch(DomainException|InvalidArgumentException $e){if($pdo->inTransaction())$pdo->rollBack();floodguardJsonResponse(422,['success'=>false,'message'=>$e->getMessage()]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();if(isset($stored['absolute_path'])&&is_file($stored['absolute_path']))unlink($stored['absolute_path']);error_log('[Resident resubmit] '.$e->getMessage());floodguardJsonResponse(500,['success'=>false,'message'=>'Unable to resubmit the flood report.']);}
